const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {chromium,devices}=require(process.env.SCIMUX_E2E_PLAYWRIGHT);
const source=process.argv[2],out=process.argv[3];fs.mkdirSync(out,{recursive:true,mode:0o700});
const links=fs.readFileSync(path.join(source,'web/index.html'),'utf8').match(/<link rel="stylesheet" href="[^"]+">/g).join('\n');
const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">${links}</head><body><section id="chat" class="panel" style="display:flex"><div id="msgwrap"><div id="msgs"><div class="turn user media"><div class="bubble"><div class="gwho">You</div><div class="attrow"><a class="attfile" href="#"><span id="target">synthetic-source.txt</span></a></div></div></div></div></div></section></body></html>`;
const server=http.createServer((req,res)=>{const name=new URL(req.url,'http://fixture').pathname;if(name==='/'){res.setHeader('Content-Type','text/html');res.end(html);return;}if(/^\/css\/[a-z-]+\.css$/.test(name)){res.setHeader('Content-Type','text/css');res.end(fs.readFileSync(path.join(source,'web',name)));return;}res.writeHead(404);res.end();});
(async()=>{await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));let browser;const samples=[];try{browser=await chromium.launch();for(const mode of ['desktop','phone'])for(const colorScheme of ['light','dark']){const context=await browser.newContext({...mode==='phone'?devices['iPhone 13']:{viewport:{width:1280,height:900}},colorScheme});try{const page=await context.newPage();await page.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});const sample=await page.locator('#target').evaluate(el=>{const parse=s=>{const a=s.match(/[\d.]+/g)?.map(Number)||[];return a.length===3?[...a,1]:a;};let bg=[255,255,255,1];const chain=[];for(let n=el;n;n=n.parentElement)chain.unshift(n);for(const n of chain){const c=parse(getComputedStyle(n).backgroundColor);if(c.length===4){bg=[c[0]*c[3]+bg[0]*(1-c[3]),c[1]*c[3]+bg[1]*(1-c[3]),c[2]*c[3]+bg[2]*(1-c[3]),1];}}const fg=parse(getComputedStyle(el).color);const lum=c=>c.slice(0,3).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0);const a=lum(fg),b=lum(bg),box=el.getBoundingClientRect();return {foreground:fg,background:bg,contrast:(Math.max(a,b)+.05)/(Math.min(a,b)+.05),visible:box.width>0&&box.height>0};});samples.push({mode,colorScheme,...sample});await page.screenshot({path:path.join(out,mode+'-'+colorScheme+'.png'),fullPage:true});}finally{await context.close();}}fs.writeFileSync(path.join(out,'contrast.json'),JSON.stringify(samples,null,2));console.log(JSON.stringify(samples));assert.ok(samples.every(s=>s.visible&&s.contrast>=4.5),'common file-only user attachment contrast is below4.5:1');}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}})().catch(err=>{console.error(err.message);process.exitCode=1});
